import * as THREE from './vendor/three.module.js';
const V=(a)=>new THREE.Vector3(...a);
export class BastionModel {
 constructor(scene,config){this.config=config;this.root=new THREE.Group();this.root.name='The Bastion / 40m';scene.add(this.root);this.parts=[];this.sections=[];this.launchers=[];this.plates=[];this.anchor=null;this.box=new THREE.BoxGeometry(1,1,1);this.material=new THREE.MeshStandardMaterial({color:'#344b5a',metalness:.6,roughness:.65});this.dark=new THREE.MeshStandardMaterial({color:'#172631',metalness:.7,roughness:.5});this.energy=new THREE.MeshStandardMaterial({color:'#83f4ed',emissive:'#38f0eb',emissiveIntensity:1.5});
  this.addPart('hip',this.root,[0,18,0],[12,4,8]);this.torso=this.addPart('torso',this.root,[0,26,0],[13,14,8]);this.head=this.addPart('head',this.root,[0,37,0],[6,6,6]);this.mesh(this.head,[0,0,3.05],[4,.6,.2],this.energy);
  this.legs=[-1,1].map(s=>{const n=this.addPart(s<0?'left-leg':'right-leg',this.root,[s*3.8,9,0],[3.6,18,8]);this.mesh(n,[0,-6.7,.25],[4.1,3,8.4],this.dark);this.mesh(n,[0,0,4.1],[1.3,2,.18],this.energy);return n;});
  this.arms=[-1,1].map(s=>{const n=this.addPart(s<0?'left-arm':'right-arm',this.root,[s*8.2,23,0],[3.8,18,8]);this.mesh(n,[0,0,4.1],[1.2,3,.15],this.energy);return n;});
  this.root.updateMatrixWorld(true);config.launchers.positions.forEach((p,i)=>{const parent=this.parts.find(part=>part.id===config.launchers.parents[i])?.node||this.root,local=this.root.localToWorld(V(p));parent.worldToLocal(local);const n=this.addPart('launcher-'+i,parent,local.toArray(),config.launchers.size,this.dark);for(const x of[-.55,.55])for(const y of[-.7,.7])this.mesh(n,[x,y,p[2]>0?1.3:-1.3],[.55,.55,.16],this.energy);this.launchers.push(n);});
  for(const [i,loc]of config.core.locations.entries()){const g=new THREE.Group();g.position.copy(V(loc.position));if(loc.position[2]<0)g.rotation.y=Math.PI;this.root.add(g);const mat=new THREE.MeshStandardMaterial({color:'#385265',metalness:.7,roughness:.5,emissive:'#102c35',emissiveIntensity:.4});const plate=this.mesh(g,[0,0,0],[2.9,3,.25],mat),core=this.mesh(g,[0,0,.12],[config.core.radius*2,config.core.radius*2,.32],new THREE.MeshStandardMaterial({color:'#c7fff7',emissive:'#32ffcf',emissiveIntensity:3}));this.plates.push({group:g,plate,core,material:mat,index:i});}
  this.routePatches=[];for(const id of config.routes.ids){const node=this.legs[id.includes('left')?0:1],mat=new THREE.MeshBasicMaterial({color:config.routes.warningColor,transparent:true,opacity:.7});const patch=this.mesh(node,[0,3,id.includes('front')?4.15:-4.15],config.routes.patchSize,mat);patch.visible=false;this.routePatches.push({id,patch});}this.debugExtras=[];this.debug=new THREE.Group();this.root.add(this.debug);const debugMaterial=new THREE.MeshBasicMaterial({color:config.debug.hitboxColor,wireframe:true,transparent:true,opacity:.35,depthWrite:false});for(const s of this.sections){const b=this.mesh(s.node,[0,s.cap?this.sections.find(q=>q.node===s.node&&!q.cap).size[1]/2:0,0],s.size,debugMaterial);b.userData.bastionDebug=true;s.debug=b;}for(const p of this.plates){const wire=this.mesh(p.group,[0,0,0],[config.core.radius*2,config.core.radius*2,.8],debugMaterial);this.debugExtras.push(wire);}this.root.scale.setScalar(config.body.height/40);this.sync();this.setDebug(config.debug.enabled);
 }
 mesh(parent,p,size,material){const m=new THREE.Mesh(this.box,material);m.position.copy(V(p));m.scale.copy(V(size));m.castShadow=m.receiveShadow=true;parent.add(m);return m;}
 addPart(id,parent,p,size,material=this.material){const g=new THREE.Group();g.name=id;g.position.copy(V(p));parent.add(g);const mesh=this.mesh(g,[0,0,0],size,material.clone());const section={id:'bastion-'+id,building:'bastion',type:'wall',state:'intact',hidden:false,collisionDisabled:false,baseSize:[...size],size:[...size],node:g,mesh,body:{position:new THREE.Vector3(),quaternion:new THREE.Quaternion()}};this.sections.push(section);this.parts.push({id,node:g,section,material:mesh.material});
  // Walkable caps let the unchanged wall-run controller crest onto limb/torso roofs.
  const cap={...section,id:section.id+'-cap',type:'slab',baseSize:[size[0],.15,size[2]],size:[size[0],.15,size[2]],cap:true,body:{position:new THREE.Vector3(),quaternion:new THREE.Quaternion()}};this.sections.push(cap);return g;
 }
 setDebug(enabled){this.debug.visible=enabled;for(const m of this.debugExtras)m.visible=enabled;for(const s of this.sections)if(s.debug)s.debug.visible=enabled;}
 sync(){this.root.updateMatrixWorld(true);for(const s of this.sections){s.size=s.baseSize.map(v=>v*this.config.body.height/40);s.body.position.copy(s.node.getWorldPosition(new THREE.Vector3()));s.body.quaternion.copy(s.node.getWorldQuaternion(new THREE.Quaternion()));if(s.cap)s.body.position.add(new THREE.Vector3(0,(this.sections.find(q=>q.node===s.node&&!q.cap)?.size[1]||0)/2,0).applyQuaternion(s.body.quaternion));s.x=s.body.position.x;s.y=s.body.position.y;s.z=s.body.position.z;} }
 animate(dt,time,player,defeated=false){if(!defeated&&player){const yaw=Math.atan2(player.x,player.z),d=Math.atan2(Math.sin(yaw-this.root.rotation.y),Math.cos(yaw-this.root.rotation.y));this.root.rotation.y+=THREE.MathUtils.clamp(d,-this.config.body.turnRate*dt,this.config.body.turnRate*dt);}for(let i=0;i<2;i++){this.legs[i].rotation.z=Math.sin(time*this.config.body.animationRate+i*Math.PI)*this.config.body.legSwing;this.arms[i].rotation.z=Math.sin(time*this.config.body.animationRate*.8+i*Math.PI)*this.config.body.armSwing;}this.sync();}
 carry(motion){const a=this.anchor;if(!a||motion.mode==='air'||motion.support?.building!=='bastion')return;const p=a.local.clone().applyMatrix4(a.section.node.matrixWorld),delta=p.sub(V([motion.position.x,motion.position.y,motion.position.z]));if(delta.length()>this.config.traversal.maxCarryDistance){this.anchor=null;return;}motion.position.x+=delta.x;motion.position.y+=delta.y;motion.position.z+=delta.z;const n=a.normal.clone().applyQuaternion(a.section.body.quaternion);motion.normal={x:n.x,y:n.y,z:n.z};return Math.atan2(Math.sin(this.root.rotation.y-a.yaw),Math.cos(this.root.rotation.y-a.yaw));}
 capture(motion){const s=motion.support;if(!s||s.building!=='bastion'||motion.mode==='air'){this.anchor=null;return;}this.anchor={yaw:this.root.rotation.y,section:s,local:s.node.worldToLocal(V([motion.position.x,motion.position.y,motion.position.z])),normal:V([motion.normal.x,motion.normal.y,motion.normal.z]).applyQuaternion(s.body.quaternion.clone().invert())};}
 world(p){return this.root.localToWorld(V(p));}
 corePoint(index){return this.plates[index].group.localToWorld(new THREE.Vector3(0,0,.35));}
 launcherPoint(index){return this.launchers[index].localToWorld(new THREE.Vector3(0,0,this.config.launchers.positions[index][2]>0?1.5:-1.5));}
 shapes(state){this.sync();const shapes=this.sections.filter(s=>!s.cap&&!s.hidden).map(s=>({center:s.body.position.clone(),half:{x:s.size[0]/2,y:s.size[1]/2,z:s.size[2]/2},rotation:s.body.quaternion.clone(),part:s.id.includes('launcher-')?s.id.replace('bastion-',''):'armour'}));for(const p of this.plates)shapes.push({center:p.group.getWorldPosition(new THREE.Vector3()),half:{x:(p.index===state.coreIndex&&state.exposed?this.config.core.radius:1.45)*this.config.body.height/40,y:(p.index===state.coreIndex&&state.exposed?this.config.core.radius:1.5)*this.config.body.height/40,z:.4*this.config.body.height/40},rotation:p.group.getWorldQuaternion(new THREE.Quaternion()),part:p.index===state.coreIndex?'core':'armour'});return shapes;}
 reset(){this.root.rotation.set(0,0,0);this.root.position.set(0,0,0);this.anchor=null;for(const s of this.sections){s.hidden=s.collisionDisabled=false;s.node.visible=true;}this.sync();}
}
